// Generated by MCSuperMods from the msm/<namespace>/entity/*.json definitions and the msm:throwable components.
package msm_test.client;

import msm_test.ModEntities;
import msm_test.client.entity.GeoModelBase;
import msm_test.client.entity.RgArcherModel;
import msm_test.client.entity.RgDartThrowerModel;
import msm_test.client.entity.RgLookoutModel;
import msm_test.client.entity.RgShortModel;
import msm_test.client.entity.RgSnowmanModel;
import msm_test.entity.ThrownItemEntity;
import net.fabricmc.api.ClientModInitializer;
import net.minecraft.client.renderer.entity.EntityRenderers;
import net.minecraft.client.renderer.entity.ThrownItemRenderer;

/** Client entrypoint: vanilla's thrown item renderer and a GeckoLib renderer per entity type. */
public final class MsmTestModClient implements ClientModInitializer {
    // Renderer providers are read when the client builds its entity renderers, after client initialisation.
    @Override
    public void onInitializeClient() {
        // Thrown items: their item model as a camera-facing sprite, as a snowball.
        EntityRenderers.register(ThrownItemEntity.TYPE, ThrownItemRenderer<ThrownItemEntity>::new);
        RgArcherModel rgArcherModel = new RgArcherModel();
        EntityRenderers.register(ModEntities.RG_ARCHER, ctx -> GeoModelBase.renderer(ctx, rgArcherModel, 1.0f));
        RgDartThrowerModel rgDartThrowerModel = new RgDartThrowerModel();
        EntityRenderers.register(ModEntities.RG_DART_THROWER, ctx -> GeoModelBase.renderer(ctx, rgDartThrowerModel, 1.0f));
        RgLookoutModel rgLookoutModel = new RgLookoutModel();
        EntityRenderers.register(ModEntities.RG_LOOKOUT, ctx -> GeoModelBase.renderer(ctx, rgLookoutModel, 1.0f));
        RgShortModel rgShortModel = new RgShortModel();
        EntityRenderers.register(ModEntities.RG_SHORT, ctx -> GeoModelBase.renderer(ctx, rgShortModel, 1.0f));
        RgSnowmanModel rgSnowmanModel = new RgSnowmanModel();
        EntityRenderers.register(ModEntities.RG_SNOWMAN, ctx -> GeoModelBase.renderer(ctx, rgSnowmanModel, 1.0f));
    }
}
